<dialog x-ref="editor" @click.self="!busy && $el.close()"><form class="dialog-body" @submit.prevent="save()"><div class="dialog-header"><h2 x-text="(editingId ? 'Ubah ' : 'Tambah ')+noun"></h2><button class="icon-button" type="button" @click="$refs.editor.close()" :disabled="busy" aria-label="Tutup formulir"><x-icon name="close"/></button></div><div class="form-grid"><template x-for="field in fields" :key="field[0]"><div class="field"><label :for="'record-'+field[0]" x-text="field[1]"></label><input :id="'record-'+field[0]" :type="field[2]" x-model="form[field[0]]" :required="field[3] || (field[0]==='password' && !editingId)" :minlength="field[0]==='password' ? 12 : null" :maxlength="field[0]==='password'?255:field[0]==='name'||field[0]==='full_name'?160:190" :autocomplete="field[0]==='password'?'new-password':'off'" :aria-invalid="!!errors[field[0]]"><p class="field-error" x-text="errors[field[0]]?.[0] || ''"></p></div></template><div class="field" x-show="resource==='employees'"><label for="record-position">Jabatan</label><select id="record-position" x-model="form.position_id" :required="resource==='employees'"><option value="">Pilih jabatan</option><template x-for="position in lookups.positions.filter(p=>p.is_active)" :key="position.id"><option :value="position.id" x-text="position.name"></option></template></select><p class="field-error" x-text="errors.position_id?.[0] || ''"></p></div><div class="field" x-show="resource==='employees'"><label for="record-user">Akun terkait (opsional)</label><select id="record-user" x-model="form.user_id"><option value="">Tanpa akun</option><template x-for="user in lookups.users" :key="user.id"><option :value="user.id" x-text="user.name+' · '+(user.email||user.login_nip)"></option></template></select></div><div class="field" x-show="resource==='units'"><label for="record-division">Divisi induk</label><select id="record-division" x-model="form.division_id" :required="resource==='units'"><option value="">Pilih divisi</option><template x-for="division in lookups.divisions.filter(d=>d.is_active)" :key="division.id"><option :value="division.id" x-text="division.name"></option></template></select></div><div class="full" x-show="resource==='users'"><span class="label">Kelayakan peran</span><div class="flex flex-wrap gap-4"><template x-for="role in [['kepala_unit','Kepala Unit'],['kepala_divisi','Kepala Divisi'],['super_hc','Super HC']]" :key="role[0]"><label class="inline-check"><input type="checkbox" :value="role[0]" x-model="form.roles" :disabled="typeof existingRoles !== 'undefined' && existingRoles.includes(role[0])"><span x-text="role[1]"></span></label></template></div><p class="muted small mt-2">Akses aktif mengikuti penugasan area. Gunakan pencabutan penugasan untuk menghentikan akses.</p><p class="muted small mt-2" x-show="editingId">Kosongkan kata sandi jika tidak ingin menggantinya.</p></div><label class="inline-check full"><input type="checkbox" x-model="form.is_active"><span>Status aktif</span></label></div><div class="notice notice-error mt-4" x-show="formError" role="alert"><p x-text="formError"></p><template x-for="(messages,key) in errors" :key="key"><p class="small mt-1" x-text="messages[0]"></p></template></div><div class="dialog-footer"><button class="btn" type="button" :disabled="busy" @click="$refs.editor.close()">Batal</button><button class="btn btn-primary" type="submit" :disabled="busy" x-text="busy?'Menyimpan…':'Simpan perubahan'"></button></div></form></dialog>
